+/// Load a config value and validate it is a mapping (or null/empty).
+///
+/// Returns `Ok(Some(value))` for valid mappings, `Ok(None)` for null
+/// (empty/comments-only files), and `Err` for non-mapping YAML values
+/// like scalars or arrays that cannot represent a config.
+fn load_and_validate_config_value(path: &Path) -> Result<Option<serde_yaml::Value>> {
+    let value = load_config_value(path)?;
+    match &value {
+        serde_yaml::Value::Null => {
+            tracing::warn!(
+                "Config file {} is empty or contains only comments — it has no effect",
+                path.display()
+            );
+            Ok(None)
+        }
+        serde_yaml::Value::Mapping(_) => Ok(Some(value)),
+        _ => Err(BivvyError::ConfigParseError {
+            path: path.to_path_buf(),
+            message: format!(
+                "Expected a YAML mapping but found {}. Config files must contain key-value pairs.",
+                yaml_type_name(&value)
+            ),
+        }),
+    }
+}
