-        configs.push(load_config_value(p)?);
+        if let Some(v) = load_and_validate_config_value(p)? {
+            configs.push(v);
+        }
     }

     // 2. User global
     if let Some(p) = &paths.user_global {
-        configs.push(load_config_value(p)?);
+        if let Some(v) = load_and_validate_config_value(p)? {
+            configs.push(v);
+        }
     }

     // 3. Project config
     if let Some(p) = &paths.project {
-        configs.push(load_config_value(p)?);
+        if let Some(v) = load_and_validate_config_value(p)? {
+            configs.push(v);
+        }
     }

     // 4. Split-file steps
@@ -545,7 +590,9 @@ fn collect_config_values(

