     }
+
+    // --- Invalid config warning tests ---
+
+    #[test]
+    fn load_merged_config_survives_empty_local_override() {
+        // If config.local.yml is empty (all comments), it should NOT wipe
+        // the project config. The project config should be preserved.
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            r#"
+app_name: MyApp
+steps:
